import numpy as np, itertools
e=df['eps'].values; t=df['T'].values; s=df['sigma'].values
B={}
ex={'1':np.ones_like(e),'exp(-e/T)':np.exp(-e/t),'exp(-e)':np.exp(-e),'exp(-T)':np.exp(-t),'exp(-1/T)':np.exp(-1/t),'exp(-2e/T)':np.exp(-2*e/t),'exp(-e*T)':np.exp(-e*t)}
